None.ex:
def keres(lista, x):
    for v in lista:
        if v == x:
            return v
    return None

print(keres(['A'], 'B'))   # None

utkozik.ex:
def utkozik(vezerek, oszlop):
    sor = len(vezerek)
    return any(o == oszlop or abs(o - oszlop) == sor - s
               for s, o in enumerate(vezerek))

print(utkozik((0,), 1))   # True (átló)
print(utkozik((0,), 2))   # False

